import{z as s,x as i,o as A,c as d,q as o,j as l,D as e,d as r,s as n,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"ESG 因子争论","description":"","frontmatter":{"title":"ESG 因子争论","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/esg-factor-debate.md","filePath":"quant/esg-factor-debate.md","lastUpdated":1791063341000}'),p={name:"quant/esg-factor-debate.md"};function m(u,a,D,b,h,F){const t=i("Mermaid");return A(),d("div",null,[a[2]||(a[2]=o('<h1 id="esg-因子争论" tabindex="-1">ESG 因子争论 <a class="header-anchor" href="#esg-因子争论" aria-label="Permalink to &quot;ESG 因子争论&quot;">​</a></h1><div class="epigraph"><p>ESG 分数既可能是风险补偿、也可能是偏好导致的需求曲线，还可能只是数据供应商之间的噪声；三种机制要求三种完全不同的组合回应。</p><footer>—— Pástor, Stambaugh and Taylor, Journal of Financial Economics, 2021；分数分歧见 Berg, Kölbel and Rigobon</footer></div><p><a href="/quant/buyback-flows">上一课</a>把发行人买盘当成机械流。ESG 的缺口是<strong>另一类非现金流转的需求</strong>：委托、标签与基金章程把资本推向高分名字。金融栏有 ESG 理论，本课不重写伦理或福利。量化栏要决定：它是因子、是约束、还是数据。不要把绿色组合相对市场的超额再拿去跑一遍 <a href="/quant/capm">CAPM</a> 当「发现」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Pástor–Stambaugh–Taylor 与 Pedersen–Fitzgibbons–Pomorski 给出均衡语言：若投资人偏好可持续资产，高 ESG 的预期收益可以更低（已付更高价格），气候风险暴露则要求补偿。实证上两股力量对谁占上风随样本变。Berg–Kölbel–Rigobon 记录评级商之间的「加总混乱」：同一公司在不同供应商处分差极大，于是「ESG 因子」不可复现。问题是产品层必须先选机制：当风险因子就该进 <a href="/quant/fundamental-risk-model">基本面风险模型</a>；当偏好流就该当约束与拥挤；当噪声就不该进信号。</p><p><span class="marginnote">术语翻译：「偏好流」就是「有人愿意为标签多付钱」——像球迷为正版球衣多付几百块，球衣并没有更好穿。买价被推高意味着未来收益被压低，这不是市场失灵，是偏好进入价格的正常结果。</span></p><p>Hartzmark–Sussman 显示可持续标签引发资金流动。流可以制造短期超额，随后是更低的长期预期收益。这与被动纳入是同一类需求曲线，不是新的 HML。</p><h3 id="分数不是会计" tabindex="-1">分数不是会计 <a class="header-anchor" href="#分数不是会计" aria-label="Permalink to &quot;分数不是会计&quot;">​</a></h3><p>价值因子至少有账面、盈余等可复算投入。ESG 分数是供应商的黑盒加权。换商、换权重，多空组合几乎换一批名字。研究日志必须冻结供应商与版本，否则发表后的「失效」只是数据修订。</p><p><span class="marginnote">把排除清单（武器、煤炭）当成因子收益，会把行业赌注叫做 ESG alpha。应先行业中性，再看残差是否还值借券与跟踪误差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种用法分开回测：风险暴露（气候、争议事件）、偏好约束（跟踪误差最小化加排除）、分数动量（流的代理）。对照：换评级商的稳健性；相对价值、质量、低波动的正交。容量：标签基金的申赎与指数纳入同步时，拥挤与 ESG 流合一。</p>',12)),(A(),l(B,null,{default:e(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%89%8B%E4%B8%8A%E6%9C%89%E4%B8%80%E6%9D%A1%20ESG%20%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20Q1%7B%22%E6%8D%A2%E4%B8%80%E5%AE%B6%E8%AF%84%E7%BA%A7%E5%95%86%E8%BF%98%E6%88%90%E7%AB%8B%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20A%5B%22%E6%B5%8B%E9%87%8F%E5%99%AA%E5%A3%B0%3A%20%E4%B8%8D%E8%BF%9B%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20Q2%7B%22%E8%B6%85%E9%A2%9D%E4%BC%B4%E9%9A%8F%E6%A0%87%E7%AD%BE%E8%B5%84%E9%87%91%E6%B5%81%E5%85%A5%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20B%5B%22%E5%81%8F%E5%A5%BD%E6%B5%81%3A%20%E5%BD%93%E7%BA%A6%E6%9D%9F%E4%B8%8E%E6%8B%A5%E6%8C%A4%E7%AE%A1%E7%90%86%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20Q3%7B%22%E5%AF%B9%E5%BA%94%E5%8F%AF%E8%AF%86%E5%88%AB%E7%9A%84%E9%A3%8E%E9%99%A9%E6%BA%90%E5%90%97%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E9%A3%8E%E9%99%A9%E5%9B%A0%E5%AD%90%3A%20%E8%BF%9B%E9%A3%8E%E9%99%A9%E6%A8%A1%E5%9E%8B%E5%B9%B6%E8%A6%81%E6%B1%82%E8%A1%A5%E5%81%BF%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20D%5B%22%E5%9B%9E%E5%AE%9E%E9%AA%8C%E5%AE%A4%3A%20%E6%8D%A2%E6%A0%B7%E6%9C%AC%E4%B8%8E%E6%AD%A3%E4%BA%A4%E6%A3%80%E9%AA%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"数字实例：Berg 等人记录两家评级商对同一公司的分数相关度只有约 0.4–0.7，而信用评级之间的相关接近 0.99。按 A 商选的多空名单与按 B 商选的可以几乎不重叠——先问你的信号依赖哪一家、哪一版，再谈「因子失效」。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"偏好移动需求曲线；风险补偿移动供给价格；测量误差增加残差。短期内流可以主导，长期内若偏好持续，高分资产的折现率可以更低。策略若两边都想赚，会自我矛盾。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：把「ESG 组合近三年跑赢」当成 ESG 是好因子的证据。短期超额更常来自标签资金持续流入推价；若偏好真的长期持续，高分资产价格更贵、未来预期收益反而更低。看超额时务必同时看流入数据与持有期长短。")],-1)),(A(),l(B,null,{default:e(()=>[n(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Score%5B%22ESG%20%E5%88%86%E6%95%B0%22%5D%20--%3E%20Noise%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E5%88%86%E6%AD%A7%22%5D%0A%20%20Pref%5B%22%E5%A7%94%E6%89%98%E4%B8%8E%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20Flow%5B%22%E9%9C%80%E6%B1%82%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20Risk%5B%22%E6%B0%94%E5%80%99%E7%AD%89%E9%A3%8E%E9%99%A9%22%5D%20--%3E%20Prem%5B%22%E8%A6%81%E6%B1%82%E8%A1%A5%E5%81%BF%22%5D%0A%20%20Flow%20--%3E%20Px%5B%22%E7%9F%AD%E6%9C%9F%E4%BB%B7%E6%A0%BC%20%E9%95%BF%E6%9C%9F%E9%A2%84%E6%9C%9F%E6%94%B6%E7%9B%8A%22%5D%0A%20%20Prem%20--%3E%20Px%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评判可持续投资的规范价值。监管披露与漂绿是法律与产品问题，不是回测调参对象。金融栏理论课此处只链接。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ESG 要先选机制：风险、偏好流、或噪声，不能三者一起当 alpha。</li><li>评级分歧使因子不可复现，必须冻结数据版本。</li><li>标签流与纳入流同类，先中性行业与质量。</li><li>出处：Pástor, Stambaugh and Taylor, <em>JFE</em>, 2021；Pedersen, Fitzgibbons and Pomorski；Berg, Kölbel and Rigobon 对评级分歧。</li></ul>',4))])}const C=s(p,[["render",m]]);export{S as __pageData,C as default};
